<?php
require_once __DIR__.'/bootstrap.php';require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';
 if($a==='add'){$start=str_replace('T',' ',trim((string)$_POST['starts_at']));if(strlen($start)===16)$start.=':00';db()->prepare('INSERT INTO games(starts_at,competition,home_team,away_team,status,channel_keywords,stream_id) VALUES(?,?,?,?,?,?,?)')->execute([$start,trim((string)$_POST['competition']),trim((string)$_POST['home_team']),trim((string)$_POST['away_team']),'scheduled',trim((string)$_POST['channel_keywords']),trim((string)$_POST['stream_id'])]);$id=(int)db()->lastInsertId();audit_log('game.create','game',$id);$_SESSION['flash']='Jogo adicionado.';}
 if($a==='score'){$hs=$_POST['home_score']===''?null:(int)$_POST['home_score'];$as=$_POST['away_score']===''?null:(int)$_POST['away_score'];$id=(int)$_POST['id'];db()->prepare('UPDATE games SET home_score=?,away_score=?,status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$hs,$as,(string)$_POST['status'],$id]);audit_log('game.score','game',$id);$_SESSION['flash']='Placar atualizado.';}
 if($a==='delete'){$id=(int)$_POST['id'];db()->prepare('DELETE FROM games WHERE id=?')->execute([$id]);audit_log('game.delete','game',$id);$_SESSION['flash']='Jogo removido.';}
 header('Location:games.php');exit;}
$rows=db()->query("SELECT * FROM games WHERE starts_at >= datetime('now','-1 day') ORDER BY starts_at ASC LIMIT 100")->fetchAll();$pageTitle='Jogos do Dia';include __DIR__.'/partials/header.php';
?>
